{
  "checks": [
    {
      "problem": "链路明细里每个产品只展示开头几步的截图，后面的步骤没有图，读者无法在页面上核对问题清单和结论提到的那些界面。",
      "A": "没解决",
      "B": "解决"
    },
    {
      "problem": "问题清单、改进建议和链路明细之间没有互相引用的定位信息（问题编号、步骤号、屏名），读者要在几节之间来回数步骤、对编号才能把问题、建议和对应界面一一对上。",
      "A": "部分解决",
      "B": "解决"
    }
  ],
  "worse": [
    {
      "version": "A",
      "where": "链路明细（交互链路）一节",
      "why": "每款 App 只给出前 4 步截图，导致上方「关键环节」表里的「附加产品」「退改规则」「确认与支付」三行在链路里根本没有可对照的界面，关键指标又写着「分析截图 27 张」而页面只出现 16 张，读者会以为后面步骤被遗漏，只能回流程对比表自己数步骤。"
    }
  ],
  "better": "B",
  "reason": "B 的链路明细把每款 App 的每一步都配了截图，并在步骤标题旁直接标出问题编号（如云途第 3 步·选择舱位·P5、第 5 步·接送机·P4，北极星第 4 步·确认订单·P3），读者从问题明细或改进建议能一步跳到对应界面；A 只画到第 4 步、且链路里没有问题编号，仍要靠数步骤、翻页去找。",
  "next": [
    {
      "where": "关键环节表 与 链路明细 之间",
      "task": "核对同一环节（选舱位、附加产品、退改规则、确认与支付）在四款 App 里的差别",
      "why": "关键环节表在上方，链路明细在很靠下的位置并按产品分组，两者之间没有步骤号或锚点对应，读者要上下长距离滚动并记住每款 App 的步骤位置，才能把表格里的结论和截图对上。"
    },
    {
      "where": "链路明细内部",
      "task": "横向比较四款 App 处于同一环节的那一屏（例如「附加产品」是 3 屏默认勾选、1 屏默认勾选还是 1 屏默认不选）",
      "why": "截图按产品分组、每行 3 张平铺，产品之间只有小标题分隔，没有按环节对齐的行；要比较同一环节必须在四段图之间来回滚动，并且缩略图很小，得不断在图片和下方说明文字之间上下对照。"
    }
  ]
